	" . $_POST['include'] . "
";
}", "source": "POST 参数 include", "source_kind": "body", "source_name": "include", "tainted_expression": "$_POST['include']", "sink": "$page['body'] 字符串拼接后输出到 HTML 响应（模板渲染 body）", "endpoint": "/021.php", "http_method": "POST", "exploit_chain": [{"step": 1, "location": "021.php:14", "description": "检测到 POST 参数 include 存在", "data_state": "原始攻击者输入 $_POST['include']"}, {"step": 2, "location": "021.php:15-17", "description": "将 include 值直接字符串拼接到 $page['body']，无 htmlspecialchars/实体编码", "data_state": "未编码的 HTML/JS 片段进入页面 body"}, {"step": 3, "location": "021.php:3-5", "description": "响应头设置固定 nonce 的 CSP，攻击者可在 payload 中复用同一 nonce 使内联脚本被允许执行", "data_state": "CSP 因 nonce 可预测而失效", "bypass_reason": "nonce 硬编码在源码中，攻击者可直接读取并复用"}, {"step": 4, "location": "021.php:8", "description": "X-XSS-Protection: 0 关闭浏览器反射型 XSS 过滤", "data_state": "浏览器不再拦截", "bypass_reason": "显式关闭 XSS 审计"}], "poc": {"description": "向 021.php 提交带固定 nonce 的 script 标签，绕过 CSP 执行 alert", "preconditions": ["目标 021.php 可被 HTTP 访问", "外层模板将 $page['body'] 输出到响应"], "steps": [{"step": 1, "action": "提交包含固定 nonce 的 script 标签", "request": "POST /021.php HTTP/1.1
